// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    // fuzz the block offset (how many blocks ahead the contract recorded) and the caller key
    function testFuzz_property(uint8 blockOffset, uint256 pk) public {
        pk = bound(pk, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep blockOffset small but wide enough (0..255). We need at least a chance to pick 0
        // (which is the distinguishing case: guess.block = currentBlock + 1, so calling settle at same block happens when blockOffset==0)
        // but don't constrain out other values
        // construct an address from the private key
        address player = vm.addr(pk);
        // fund player so it can send 1 ether
        vm.deal(player, 5 ether);

        // ensure we are at a known block number
        uint256 startBlock = block.number;

        // the reference contract sets guesses[msg.sender].block = block.number + 1 during lockInGuess
        // We'll simulate timing by optionally advancing blocks before calling settle.

        // lock in a guess from player
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked("dummy")));

        // Now decide how many blocks to advance: use blockOffset as the number of blocks to advance after locking.
        // We bound it to a smaller window so forge fuzz stays practical but still includes 0 which is critical.
        uint256 advance = uint256(blockOffset) % 8; // keep within 0..7 blocks
        for (uint256 i = 0; i < advance; i++) {
            vm.roll(block.number + 1);
        }

        // The distinguishing case is when advance == 0: then immediately after locking
        // guesses[player].block == startBlock + 1, and current block == startBlock, so
        // calling settle at this moment has block.number == guesses[player].block - 1 (i.e. <), so both revert.
        // BUT the mutant that uses >= allows settling at the same block as recorded value; to trigger that
        // we need to call settle in the block equal to guesses[player].block. To reach that, advance must be 1.
        // So the mutant will differ for some fuzzed inputs (notably advance==1). We must not exclude them.

        // Move to the target block for settle call: we want to call settle either at the same block as guesses[player].block
        // or before it. The reference guarantees that calling settle in the exact same block as guesses[player].block WILL REVERT.
        // We'll arrange to call settle at block = startBlock + 1 (which equals guesses[player].block), by advancing one more block
        // when desired. Use a branch based on the fuzzed blockOffset to let fuzzer find the differing case.

        // If advance was 0..6, we can choose to advance 1 more to align with guesses[player].block.
        // Do that deterministically: always advance until block.number == startBlock + 1
        // This ensures we test the case of calling settle at the recorded block.
        vm.roll(startBlock + 1);

        // Now call settle from player and record whether it reverted.
        bool ok;
        vm.prank(player);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (the single assertion): In the reference contract, calling settle when block.number == guesses[player].block MUST REVERT,
        // so ok must be false. The mutant that uses >= instead of > will allow settle to proceed (ok==true) for some inputs (notably when we call
        // at the exact recorded block), so this assertion will fail on the mutant for some fuzz values.
        assertTrue(!ok);
    }
}
